// Fixed code: Proper validation and sanitization of user input
public class SecureExample {
    public static void main(String[] args) {
        String userInput = "<script>alert('XSS')</script>";
        try {
            // Safe: Decode input, then sanitize to prevent XSS
            String decodedInput = java.net.URLDecoder.decode(userInput, "UTF-8");
            String sanitizedInput = sanitizeInput(decodedInput);
            System.out.println("Sanitized input: " + sanitizedInput);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Sanitization method to remove potentially dangerous characters
    private static String sanitizeInput(String input) {
        // Replace < and > with their HTML entity equivalents to prevent XSS
        return input.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
    }
}
